import{z as i,x as s,o as B,c as d,q as r,j as l,D as A,d as a,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"展期日历的深入","description":"","frontmatter":{"title":"展期日历的深入","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ft-roll-calendar-deep.md","filePath":"quant/ft-roll-calendar-deep.md","lastUpdated":1791063341000}'),p={name:"quant/ft-roll-calendar-deep.md"};function D(C,E,F,m,u,h){const t=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="展期日历的深入" tabindex="-1">展期日历的深入 <a class="header-anchor" href="#展期日历的深入" aria-label="Permalink to &quot;展期日历的深入&quot;">​</a></h1><div class="epigraph"><p>期货的到期是物理，持仓的存续是选择；展期日历就是把这张选择表写成可审计的规则——持哪张、换哪张、哪一天之前必须换完。</p><footer>—— 据交易所合约规则与商品指数方法论整理；被动滚仓的需求冲击见 Mou, 2011 与 Bessembinder, Carrion, Tuttle and Venkataraman, JFE, 2016</footer></div><p><a href="/quant/etf-case-map">上一课</a>把债券组合收成一张地图，工具空间里期货那一格写着标准化、CTD 刻度与逐日盯市；但那张地图默认持仓会自己跨过到期日。主干已把展期拆过几次：<a href="/quant/roll-yield">展期收益</a>记收益账，<a href="/quant/roll-volume-oi">展期成交量与持仓</a>记订单流账，<a href="/quant/seasonal-roll">季节性展期</a>记库存季节账。本课程是「期货与展期深化」的第一课，对象换成持仓本身：逐日盯市的头寸如何在到期约束下连续存在。第一课钉日历。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「哪张是主力、哪天换月」没有唯一答案：日历由三层规则叠成。第一层是交易所条款：合约循环、最后交易日、交割通知日（first notice day）、限额分档收紧的日程。第二层是流动性迁移：成交与持仓从近月滑向次近月的日期，每年每品种都在漂。第三层是被动与制度日程：商品指数公开的滚仓窗（如第五至第九个工作日）、复制产品为压跟踪误差提前的日子。三层常互相矛盾：指数说这几天走，成交说上周就该走，条款说不能晚于通知日前五天。</p><p>错在哪：把到期日当滚仓日，你会撞进交割月——深度塌掉、限额生效、空头可能被指派交割；把官方指数日当唯一高峰，你会漏掉抢跑前移后的真实冲击，见<a href="/quant/roll-volume-oi">展期成交量与持仓</a>；把主力判据从持仓穿越改成日期穿越，同一段历史会换出不同的连续价格，回测与实盘从此不是同一个策略。</p><p><span class="marginnote">数字实例：设某品种 5 月合约通知日为 4 月 30 日、最后交易日 5 月 15 日、指数滚仓窗是当月第五至第九个工作日。持仓穿越 4 月下旬已发生，而指数窗要到 5 月才开——截止日取条款日期的最小者再减安全垫，最晚 4 月下旬必须动，不能等指数窗。</span></p><h3 id="截止日不是到期日" tabindex="-1">截止日不是到期日 <a class="header-anchor" href="#截止日不是到期日" aria-label="Permalink to &quot;截止日不是到期日&quot;">​</a></h3><p>可执行日历为每品种每期合约记一个<strong>截止日</strong>：\\(\\min(\\text{最后交易日},\\ \\text{通知日},\\ \\text{限额收紧日})\\) 再往前推安全垫。安全垫有据可依：交割月内深度按天衰减，保证金分档上调，接货后的清算以天计。被动多头持有的是负向选择权——过了通知日，接货义务在别人手里。</p><p><span class="marginnote">直觉类比：截止日像机场值机柜台关闭时间——飞机（交割）还没起飞，柜台一关你就上不去了。安全垫就是「提前两小时到机场」：不是飞机提前起飞，而是越靠近起飞，排队、改签的每一步都越贵。</span></p><p><span class="marginnote">通知日只存在于实物交割市场且随品种各异：农产品常在交割月前最后一周，能源金属多在交割月初。指数化产品对此最敏感——章程禁止接货，截止日由通知日而非到期日决定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把日历写成表，不写成经验。每行一个品种：合约循环与活跃月集合、切换判据、截止日规则、窗口长度。切换判据显式二选一：日历日（每月第 \\(n\\) 个工作日）或穿越（次近月持仓连续 \\(k\\) 日超过近月）。判据定下不许中途改——连续序列的收益分布与展期损益都依赖它，改判据等于换数据。窗口长度单独一列，分几日摊完由成本与择时的权衡决定，下一课再谈。</p><p>表还要有例外列：停板、合约规则修改、到期循环对上长假。例外不进表，实盘就会现想，现想的决定不可复盘。</p>',14)),(B(),l(o,null,{default:A(()=>[n(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E4%BA%A4%E6%98%93%E6%89%80%E6%9D%A1%E6%AC%BE%EF%BC%9A%E5%BE%AA%E7%8E%AF%E3%80%81%E6%9C%80%E5%90%8E%E4%BA%A4%E6%98%93%E6%97%A5%E3%80%81%E9%80%9A%E7%9F%A5%E6%97%A5%E3%80%81%E9%99%90%E9%A2%9D%22%5D%20--%3E%20DEAD%5B%22%E6%88%AA%E6%AD%A2%E6%97%A5%20%3D%20min%20%E6%9D%A1%E6%AC%BE%E6%97%A5%E6%9C%9F%20-%20%E5%AE%89%E5%85%A8%E5%9E%AB%22%5D%0A%20%20L2%5B%22%E6%88%90%E4%BA%A4%E4%B8%8E%E6%8C%81%E4%BB%93%E8%BF%81%E7%A7%BB%E8%A7%82%E6%B5%8B%22%5D%20--%3E%20JUDGE%5B%22%E5%88%87%E6%8D%A2%E5%88%A4%E6%8D%AE%EF%BC%9A%E6%97%A5%E5%8E%86%E6%97%A5%E6%88%96%E7%A9%BF%E8%B6%8A%22%5D%0A%20%20L3%5B%22%E6%8C%87%E6%95%B0%E4%B8%8E%E5%88%B6%E5%BA%A6%E6%BB%9A%E4%BB%93%E7%AA%97%22%5D%20--%3E%20JUDGE%0A%20%20DEAD%20--%3E%20TAB%5B%22%E5%B1%95%E6%9C%9F%E6%97%A5%E5%8E%86%E8%A1%A8%EF%BC%88%E5%90%AB%E4%BE%8B%E5%A4%96%E5%88%97%EF%BC%89%22%5D%0A%20%20JUDGE%20--%3E%20TAB%0A%20%20TAB%20--%3E%20OUT%5B%22%E8%BF%9E%E7%BB%AD%E5%BA%8F%E5%88%97%E8%AE%B0%E8%B4%A6%20%2B%20%E6%89%A7%E8%A1%8C%E6%8E%92%E7%A8%8B%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("截止日必须提前的机制是交割窗的流动性塌缩：临近条款日期，投机持仓被限额与保证金推离，剩下的是交割意向真实的产业户，市价单对面没有宽度。判据必须固定的机制是可复制性：日历是策略定义的一部分，同一套信号跑在不同日历上，展期腿记账不同——"),e("a",{href:"/quant/roll-yield"},"展期收益"),a("已警告被动滚法决定你分到哪块斜率。三层的张力因此可读：指数为可复制牺牲择时，穿越为效率牺牲规则性，截止日是在两者之间买保险。")],-1)),(B(),l(o,null,{default:A(()=>[n(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%8C%81%E6%9C%89%E8%BF%91%E6%9C%88%EF%BC%9A%E6%B5%81%E5%8A%A8%E6%80%A7%E6%AD%A3%E5%B8%B8%22%5D%20--%3E%20B%7B%22%E8%B7%9D%E9%80%9A%E7%9F%A5%E6%97%A5%E8%BF%98%E6%9C%89%E5%A4%9A%E8%BF%9C%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E6%97%B6%E9%97%B4%E5%85%85%E8%A3%95%22%7C%20C%5B%22%E5%8F%AF%E7%AD%89%E5%BE%85%E7%A9%BF%E8%B6%8A%E5%88%A4%E6%8D%AE%E8%A7%A6%E5%8F%91%22%5D%0A%20%20B%20--%3E%7C%22%E8%BF%9B%E5%85%A5%E5%AE%89%E5%85%A8%E5%9E%AB%22%7C%20D%5B%22%E6%88%AA%E6%AD%A2%E6%97%A5%EF%BC%9A%E6%8D%A2%E6%9C%88%E5%BF%85%E9%A1%BB%E5%AE%8C%E6%88%90%22%5D%0A%20%20C%20--%3E%20E%7B%22%E7%A9%BF%E8%B6%8A%E8%BF%9F%E8%BF%9F%E4%B8%8D%E8%A7%A6%E5%8F%91%EF%BC%9F%22%7D%0A%20%20E%20--%3E%7C%22%E8%A7%A6%E5%8F%8A%E6%88%AA%E6%AD%A2%E6%97%A5%22%7C%20D%0A%20%20D%20--%3E%20F%5B%22%E9%94%99%E8%BF%87%EF%BC%9A%E8%A2%AB%E6%8E%A8%E8%BF%9B%E4%BA%A4%E5%89%B2%E6%9C%88%22%5D%0A%20%20F%20--%3E%20G%5B%22%E6%B7%B1%E5%BA%A6%E5%A1%8C%E7%BC%A9%20%2B%20%E4%BF%9D%E8%AF%81%E9%87%91%E5%88%86%E6%A1%A3%E4%B8%8A%E8%B0%83%22%5D%0A%20%20G%20--%3E%20H%5B%22%E7%A9%BA%E5%A4%B4%E6%88%96%E8%A2%AB%E6%8C%87%E6%B4%BE%E6%8E%A5%E8%B4%A7%EF%BC%9A%E4%B9%89%E5%8A%A1%E5%9C%A8%E5%88%AB%E4%BA%BA%E6%89%8B%E9%87%8C%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">常见误区：初学者把「主力合约」当官方定义。它只是成交与持仓的观测结果，切换判据（按日期还是按穿越）由你自己选定并写进策略；判据一换，同一段历史会换出一套不同的连续价格，回测与实盘从此不是同一个策略。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>日历是约定，不是预测：它回答「什么时候必须走完」，不回答「走贵走便宜」。跨市场品种没有统一循环，每品种一行是底线。条款会改：指数方法论修订、限额与保证金调整都使历史日历失效，修改要进版本号。本课不谈走的成本与执行次序——那是接下来两课的分工；库存状态如何改日历，第四课再探。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>展期日历由三层规则合成：交易所条款、流动性迁移观测、被动指数日程，三层分开记。</li><li>可执行日历的核心是截止日：条款日期取最小再减安全垫，不由到期日定。</li><li>切换判据是策略定义的一部分，中途更换等于更换数据。</li><li>日历写成带例外列的表并可版本化，实盘不现想、复盘有据。</li><li>出处：据交易所合约规则与商品指数方法论文件整理；滚仓窗冲击见 Mou, 2011 与 Bessembinder, Carrion, Tuttle and Venkataraman, <em>JFE</em>, 2016。</li></ul>',5))])}const _=i(p,[["render",D]]);export{c as __pageData,_ as default};
